+					base_class = base_class->base_type.class_type;
+				}
+			}
+			break;
+		}
+		case GDScriptParser::DataType::ENUM:
+		case GDScriptParser::DataType::VARIANT:
+		case GDScriptParser::DataType::RESOLVING:
+			break;
+	}
+
+	return info;
